package com.skylogistics.network;
import com.skylogistics.SkyLogistics; import com.skylogistics.menu.KleisDominionWandMenu; import net.minecraft.network.RegistryFriendlyByteBuf; import net.minecraft.network.codec.StreamCodec; import net.minecraft.network.protocol.common.custom.CustomPacketPayload; import net.neoforged.neoforge.network.handling.IPayloadContext;
public record KleisMenuActionPacket(int action) implements CustomPacketPayload{public static final Type<KleisMenuActionPacket>TYPE=new Type<>(SkyLogistics.id("kleis_menu_action"));public static final StreamCodec<RegistryFriendlyByteBuf,KleisMenuActionPacket>STREAM_CODEC=StreamCodec.ofMember((p,b)->b.writeVarInt(p.action),b->new KleisMenuActionPacket(b.readVarInt()));public static void handle(KleisMenuActionPacket p,IPayloadContext c){c.enqueueWork(()->{if(c.player().containerMenu instanceof KleisDominionWandMenu m)m.handleAction(p.action);});}@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}}
